// canon.js: the canonical arguments and the decision bytes, as Go computes them
// (agent.ApprovalDecisionBytes, canonicalArgs), reproduced exactly. The golden vectors
// (agent/testdata/canonical_args_vectors.json) are generated by Go and checked against this file; a
// case this file cannot reproduce makes the page refuse to sign, never fall back.
//
// It follows Go's encoding/json decoder where it is not obvious: object keys sorted by their UTF-8
// bytes (code point order, not UTF-16 code units), duplicate keys with the last one winning,
// numbers kept as written, a lone surrogate escape and an invalid UTF-8 byte read as U+FFFD (one per
// invalid byte), nesting up to 10000, and anything that is not one JSON value (trailing text other
// than a closing bracket included) used as its trimmed bytes as they are.

const enc = new TextEncoder();

// utf8Decode reads the rune at b[i], as Go's utf8.DecodeRune: [rune, width], an invalid sequence
// being [0xFFFD, 1].
export function utf8Decode(b, i) {
  const c = b[i];
  if (c < 0x80) return [c, 1];
  const cont = (k, lo = 0x80, hi = 0xbf) => i + k < b.length && b[i + k] >= lo && b[i + k] <= hi;
  if (c >= 0xc2 && c <= 0xdf) {
    if (cont(1)) return [((c & 0x1f) << 6) | (b[i + 1] & 0x3f), 2];
  } else if (c >= 0xe0 && c <= 0xef) {
    const lo = c === 0xe0 ? 0xa0 : 0x80;
    const hi = c === 0xed ? 0x9f : 0xbf;
    if (cont(1, lo, hi) && cont(2)) return [((c & 0x0f) << 12) | ((b[i + 1] & 0x3f) << 6) | (b[i + 2] & 0x3f), 3];
  } else if (c >= 0xf0 && c <= 0xf4) {
    const lo = c === 0xf0 ? 0x90 : 0x80;
    const hi = c === 0xf4 ? 0x8f : 0xbf;
    if (cont(1, lo, hi) && cont(2) && cont(3)) {
      return [((c & 0x07) << 18) | ((b[i + 1] & 0x3f) << 12) | ((b[i + 2] & 0x3f) << 6) | (b[i + 3] & 0x3f), 4];
    }
  }
  return [0xfffd, 1];
}

// isSpace is Go's unicode.IsSpace.
function isSpace(r) {
  if (r <= 0xff) return r === 0x20 || (r >= 0x09 && r <= 0x0d) || r === 0x85 || r === 0xa0;
  return r === 0x1680 || (r >= 0x2000 && r <= 0x200a) || r === 0x2028 || r === 0x2029 || r === 0x202f || r === 0x205f || r === 0x3000;
}

// goTrimSpace is Go's bytes.TrimSpace: leading and trailing Unicode white space removed, an invalid
// byte at either end stopping the trim.
export function goTrimSpace(b) {
  let start = 0;
  while (start < b.length) {
    const [r, w] = utf8Decode(b, start);
    if (!(isSpace(r) && !(r === 0xfffd && w === 1))) break;
    start += w;
  }
  let end = b.length;
  while (end > start) {
    // utf8.DecodeLastRune: find the start of the last rune, and accept it only if it ends at end.
    let s = end - 1;
    const lim = Math.max(start, end - 4);
    while (s > lim && (b[s] & 0xc0) === 0x80) s--;
    const [r, w] = utf8Decode(b.subarray(0, end), s);
    const rune = s + w === end ? r : 0xfffd;
    const width = s + w === end ? w : 1;
    if (!isSpace(rune) || (rune === 0xfffd && width === 1)) break;
    end -= width;
  }
  return b.subarray(start, end);
}

const MAX_DEPTH = 10000;
const WS = (c) => c === 0x20 || c === 0x09 || c === 0x0a || c === 0x0d;
const HEX = (c) => (c >= 0x30 && c <= 0x39) || (c >= 0x41 && c <= 0x46) || (c >= 0x61 && c <= 0x66);

// Parsed values: strings are JS strings (never holding a lone surrogate), numbers {num: "text"},
// literals true/false/null, arrays {a: [...]}, objects {o: Map}.

// parseFirst reads the first JSON value of b, as Go's json.Decoder does, and returns
// {value, end, members} where end is the offset after it, or null when b does not start with one.
// With top, members maps each member name of a top-level object to [start, end) offsets of its
// value in b, in the order read, duplicates included (as [name, start, end] entries).
export function parseFirst(b, top = false) {
  const stack = [];
  let i = 0;
  let members = null;
  const ws = () => {
    while (i < b.length && WS(b[i])) i++;
  };
  const str = () => {
    // b[i] is the opening quote.
    i++;
    const out = [];
    for (;;) {
      if (i >= b.length) return null;
      const c = b[i];
      if (c === 0x22) {
        i++;
        return out.join('');
      }
      if (c < 0x20) return null;
      if (c === 0x5c) {
        const e = b[i + 1];
        const simple = { 0x22: '"', 0x5c: '\\', 0x2f: '/', 0x62: '\b', 0x66: '\f', 0x6e: '\n', 0x72: '\r', 0x74: '\t' }[e];
        if (simple !== undefined) {
          out.push(simple);
          i += 2;
        } else if (e === 0x75) {
          const u = hex4(i + 2);
          if (u < 0) return null;
          i += 6;
          if (u >= 0xd800 && u <= 0xdfff) {
            // Go pairs a high surrogate with a following \uXXXX low surrogate, and reads any other
            // surrogate as U+FFFD, the escape after it being read on its own.
            let paired = false;
            if (u <= 0xdbff && b[i] === 0x5c && b[i + 1] === 0x75) {
              const lo = hex4(i + 2);
              if (lo >= 0xdc00 && lo <= 0xdfff) {
                out.push(String.fromCodePoint(0x10000 + ((u - 0xd800) << 10) + (lo - 0xdc00)));
                i += 6;
                paired = true;
              }
            }
            if (!paired) out.push('\ufffd');
          } else {
            out.push(String.fromCharCode(u));
          }
        } else {
          return null;
        }
        continue;
      }
      if (c < 0x80) {
        out.push(String.fromCharCode(c));
        i++;
        continue;
      }
      const [r, w] = utf8Decode(b, i);
      out.push(String.fromCodePoint(r));
      i += w;
    }
  };
  const hex4 = (p) => {
    if (p + 4 > b.length) return -1;
    let v = 0;
    for (let k = 0; k < 4; k++) {
      if (!HEX(b[p + k])) return -1;
      v = v * 16 + parseInt(String.fromCharCode(b[p + k]), 16);
    }
    return v;
  };
  const num = () => {
    const s = i;
    if (b[i] === 0x2d) i++;
    if (b[i] === 0x30) i++;
    else if (b[i] >= 0x31 && b[i] <= 0x39) while (b[i] >= 0x30 && b[i] <= 0x39) i++;
    else return null;
    if (b[i] === 0x2e) {
      i++;
      if (!(b[i] >= 0x30 && b[i] <= 0x39)) return null;
      while (b[i] >= 0x30 && b[i] <= 0x39) i++;
    }
    if (b[i] === 0x65 || b[i] === 0x45) {
      i++;
      if (b[i] === 0x2b || b[i] === 0x2d) i++;
      if (!(b[i] >= 0x30 && b[i] <= 0x39)) return null;
      while (b[i] >= 0x30 && b[i] <= 0x39) i++;
    }
    return { num: String.fromCharCode(...b.subarray(s, i)) };
  };
  const lit = (word, val) => {
    for (let k = 0; k < word.length; k++) if (b[i + k] !== word.charCodeAt(k)) return undefined;
    i += word.length;
    return val;
  };

  let want = 'value';
  let done;
  // attach hands a completed value to its parent, or finishes at the top.
  const attach = (v, start) => {
    if (stack.length === 0) {
      done = v;
      return;
    }
    const top = stack[stack.length - 1];
    if (top.kind === 'a') top.v.push(v);
    else {
      top.v.set(top.key, v);
      if (top.rec) members.push([top.key, start, i]);
    }
    want = 'sep';
  };
  for (;;) {
    if (done !== undefined) break;
    if (want === 'value') {
      ws();
      if (i >= b.length) return null;
      const c = b[i];
      const start = i;
      let v;
      if (c === 0x7b || c === 0x5b) {
        if (stack.length >= MAX_DEPTH) return null;
        const isObj = c === 0x7b;
        i++;
        ws();
        if (b[i] === (isObj ? 0x7d : 0x5d)) {
          i++;
          v = isObj ? { o: new Map() } : { a: [] };
        } else {
          const rec = top && isObj && stack.length === 0;
          if (rec) members = [];
          stack.push({ kind: isObj ? 'o' : 'a', v: isObj ? new Map() : [], key: null, rec, s: start });
          want = isObj ? 'key' : 'value';
          continue;
        }
      } else if (c === 0x22) {
        v = str();
        if (v === null) return null;
      } else if (c === 0x2d || (c >= 0x30 && c <= 0x39)) {
        v = num();
        if (v === null) return null;
      } else if (c === 0x74) {
        v = lit('true', true);
        if (v === undefined) return null;
      } else if (c === 0x66) {
        v = lit('false', false);
        if (v === undefined) return null;
      } else if (c === 0x6e) {
        v = lit('null', null);
        if (v === undefined) return null;
      } else return null;
      attach(v, start);
      continue;
    }
    if (want === 'key') {
      ws();
      if (b[i] !== 0x22) return null;
      const k = str();
      if (k === null) return null;
      ws();
      if (b[i] !== 0x3a) return null;
      i++;
      stack[stack.length - 1].key = k;
      want = 'value';
      continue;
    }
    // want === 'sep': after an element of the container on top.
    ws();
    const top2 = stack[stack.length - 1];
    const c = b[i];
    if (c === 0x2c) {
      i++;
      want = top2.kind === 'o' ? 'key' : 'value';
    } else if ((top2.kind === 'a' && c === 0x5d) || (top2.kind === 'o' && c === 0x7d)) {
      i++;
      stack.pop();
      attach(top2.kind === 'a' ? { a: top2.v } : { o: top2.v }, top2.s);
    } else return null;
  }
  return { value: done, end: i, members };
}

// codePointCompare orders two strings by their UTF-8 bytes, which is their code point order.
function codePointCompare(x, y) {
  let i = 0;
  let j = 0;
  while (i < x.length && j < y.length) {
    const a = x.codePointAt(i);
    const b = y.codePointAt(j);
    if (a !== b) return a < b ? -1 : 1;
    i += a > 0xffff ? 2 : 1;
    j += b > 0xffff ? 2 : 1;
  }
  if (i < x.length) return 1;
  if (j < y.length) return -1;
  return 0;
}

const hex2 = (n) => n.toString(16).padStart(4, '0');

// quote writes a string as Go's encoding/json does with HTML escaping off.
export function quote(s) {
  let out = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0);
    if (c === 0x22) out += '\\"';
    else if (c === 0x5c) out += '\\\\';
    else if (c === 0x08) out += '\\b';
    else if (c === 0x0c) out += '\\f';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c === 0x09) out += '\\t';
    else if (c < 0x20) out += '\\u' + hex2(c);
    else if (c === 0x2028 || c === 0x2029) out += '\\u' + hex2(c);
    else out += ch;
  }
  return out + '"';
}

// serialize writes a parsed value as Go's Encoder does: no white space, keys in code point order.
// It is iterative, so nesting to the decoder's limit cannot exhaust the stack.
export function serialize(root) {
  const out = [];
  const work = [root];
  while (work.length) {
    const v = work.pop();
    if (typeof v === 'function') {
      v();
      continue;
    }
    if (v === null) out.push('null');
    else if (v === true) out.push('true');
    else if (v === false) out.push('false');
    else if (typeof v === 'string') out.push(quote(v));
    else if (v.num !== undefined) out.push(v.num);
    else if (v.a) {
      out.push('[');
      work.push(() => out.push(']'));
      for (let k = v.a.length - 1; k >= 0; k--) {
        work.push(v.a[k]);
        if (k > 0) work.push(() => out.push(','));
      }
    } else {
      const keys = [...v.o.keys()].sort(codePointCompare);
      out.push('{');
      work.push(() => out.push('}'));
      for (let k = keys.length - 1; k >= 0; k--) {
        work.push(v.o.get(keys[k]));
        work.push(() => out.push(quote(keys[k]) + ':'));
        if (k > 0) work.push(() => out.push(','));
      }
    }
  }
  return enc.encode(out.join(''));
}

// canonicalArgs is Go's canonicalArgs: the arguments parsed as JSON and written with keys sorted,
// no white space and numbers as written; "{}" for none; and the trimmed bytes as they are for
// anything that is not one JSON value.
export function canonicalArgs(raw) {
  const trimmed = goTrimSpace(raw);
  if (trimmed.length === 0) return enc.encode('{}');
  const r = parseFirst(trimmed);
  if (r === null) return trimmed;
  let k = r.end;
  while (k < trimmed.length && WS(trimmed[k])) k++;
  // Go's decoder.More: anything after the value other than a closing bracket is more input.
  if (k < trimmed.length && trimmed[k] !== 0x5d && trimmed[k] !== 0x7d) return trimmed;
  return serialize(r.value);
}

const u32 = (n) => new Uint8Array([(n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff]);

// decisionBytes is agent.ApprovalDecisionBytes over argsDigest, the 32-byte SHA-256 of the
// canonical arguments (computed by the caller, from the arguments it displays).
export function decisionBytes({ run, call, tool, argsDigest, approver, approved, decidedAt }) {
  if (argsDigest.length !== 32) throw new Error('the arguments digest is not 32 bytes');
  const parts = [enc.encode('bide.approval.v3\n')];
  for (const s of [run, call, tool]) {
    const e = enc.encode(s);
    parts.push(u32(e.length), e);
  }
  parts.push(argsDigest);
  const a = enc.encode(approver);
  parts.push(u32(a.length), a, new Uint8Array([approved ? 1 : 0]));
  const d = enc.encode(decidedAt);
  parts.push(u32(d.length), d);
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}

// formatTimestamp is agent.FormatTimestamp: RFC 3339 in UTC to the millisecond, 24 bytes.
export function formatTimestamp(date) {
  const t = new Date(Math.floor(date.getTime()));
  const y = t.getUTCFullYear();
  if (y < 1 || y > 9999) throw new Error('the time has no canonical form');
  return t.toISOString().replace(/^\+?0*(\d{4,})-/, (m, yy) => yy.padStart(4, '0') + '-');
}
